package com.aadil.ecommerce.entities;import com.aadil.ecommerce.enums.OrderStatus;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import org.hibernate.annotations.CreationTimestamp;import org.hibernate.annotations.UpdateTimestamp;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;@Table(name = "orders")@Entity@Getter@Setter@NoArgsConstructorpublic class OrderEntity {    @GeneratedValue(strategy = GenerationType.IDENTITY)    @Id    @Column(name = "order_id")    private Long orderId;    @ManyToOne(fetch = FetchType.LAZY,targetEntity = UserEntity.class)    @JoinColumn(name = "user_id",nullable = false)    private UserEntity user;    @Column(nullable = false)    private BigDecimal totalAmount;    @OneToMany(mappedBy = "order",targetEntity = OrderItemEntity.class)    List<OrderItemEntity> orderItems = new ArrayList<>();    @Enumerated(value = EnumType.STRING)    @Column(nullable = false)    private OrderStatus orderStatus;    @CreationTimestamp    @Column(nullable = false,updatable = false)    private LocalDateTime createdAt;    @UpdateTimestamp    @Column(nullable = false)    private LocalDateTime updatedAt;}